import base64, hashlib, io, json, zipfile
from pathlib import Path
root = Path('products/distribution/sqlite-original-regression-exercise')
archive = root / 'private-lab-v2.zip.b64'
receipt = root / 'private-lab-v2-verification.json'
sha = lambda data: hashlib.sha256(data).hexdigest()
result = {'prior_check': 'TASK-179574660200', 'scope': 'Exact payload identity and receipt readback for the existing private listing decision. Redistribution, seller activation and settlement require separate evidence.'}
for path in (archive, receipt):
    result[path.name] = {'present': path.is_file()}
    if path.is_file():
        result[path.name]['file_sha256'] = sha(path.read_bytes())
if receipt.is_file():
    try:
        result['verification_receipt'] = json.loads(receipt.read_text())
    except (ValueError, UnicodeError) as exc:
        result['verification_receipt_error'] = str(exc)
if archive.is_file():
    try:
        payload = base64.b64decode(b''.join(archive.read_bytes().split()), validate=True)
        result['decoded_archive_sha256'] = sha(payload)
        with zipfile.ZipFile(io.BytesIO(payload)) as package:
            entries = [entry for entry in package.infolist() if not entry.is_dir()]
            if sum(entry.file_size for entry in entries) > 2_000_000:
                raise ValueError('Declared uncompressed payload exceeds inspection limit')
            result['members'] = [{'name': entry.filename, 'size': entry.file_size, 'sha256': sha(package.read(entry)), 'source_candidates': [{'path': str(path), 'same_bytes': sha(path.read_bytes()) == sha(package.read(entry))} for path in sorted(root.rglob(Path(entry.filename).name)) if path.is_file()]} for entry in entries]
            result['duplicate_member_names'] = len(entries) != len({entry.filename for entry in entries})
    except (ValueError, zipfile.BadZipFile, RuntimeError, NotImplementedError) as exc:
        result['archive_read_error'] = str(exc)
output = Path('products/distribution/sqlite-lemonsqueezy-fit/director-payload-diagnostic.json')
output.parent.mkdir(parents=True, exist_ok=True)
output.write_text(json.dumps(result, indent=2) + '\n')
print(json.dumps({key: value for key, value in result.items() if key != 'verification_receipt'}, indent=2))
